using System;using System.IO;using System.Collections;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Web.Script.Serialization;
using RT=System.Runtime.InteropServices.ComTypes.IRunningObjectTable;using BC=System.Runtime.InteropServices.ComTypes.IBindCtx;using EM=System.Runtime.InteropServices.ComTypes.IEnumMoniker;using MK=System.Runtime.InteropServices.ComTypes.IMoniker;
using interop.ICApiIronCAD;
static class PrototypeCleanup {
 [DllImport("ole32.dll")]static extern int GetRunningObjectTable(int x,out RT r);[DllImport("ole32.dll")]static extern int CreateBindCtx(int x,out BC b);
 [DllImport("user32.dll")]static extern IntPtr GetForegroundWindow();
 static JavaScriptSerializer J=new JavaScriptSerializer{MaxJsonLength=32000000};static IZBaseApp App;static string Dir;static int N;static HashSet<string> Own;
 static string Full(string p){return Path.GetFullPath(p);}static bool Same(string a,string b){return String.Equals(Full(a),Full(b),StringComparison.OrdinalIgnoreCase);}
 static Dictionary<string,object> Obj(object o){return(Dictionary<string,object>)o;}static object[] Arr(object o){return(object[])o;}
 static void Write(string path,object o){byte[] b=System.Text.Encoding.UTF8.GetBytes(J.Serialize(o));using(var f=new FileStream(path,FileMode.CreateNew,FileAccess.Write,FileShare.Read)){f.Write(b,0,b.Length);f.Flush(true);}}
 static string Hash(string p){using(var f=File.OpenRead(p))using(var h=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(h.ComputeHash(f)).Replace("-","").ToLowerInvariant();}
 static object Existing(object[] contexts){RT r;BC b;Marshal.ThrowExceptionForHR(GetRunningObjectTable(0,out r));Marshal.ThrowExceptionForHR(CreateBindCtx(0,out b));EM e;r.EnumRunning(out e);MK[] m=new MK[1];while(e.Next(1,m,IntPtr.Zero)==0){string p;try{m[0].GetDisplayName(b,null,out p);}catch{continue;}if(!Path.IsPathRooted(p))continue;foreach(object c in contexts)if(Same(p,(string)c)){object v;r.GetObject(m[0],out v);return v;}}throw new Exception("No existing explicit context, no open/activation fallback");}
 static Dictionary<string,object> State(){var d=App.ActiveDoc;return new Dictionary<string,object>{{"foreground_hwnd",GetForegroundWindow().ToInt64()},{"active_path",d==null?null:d.Name},{"active_guid",d==null?null:d.FileGUID},{"active_modified",d==null?(object)null:d.Modified}};}
 static T Guard<T>(string label,Func<T> fn){string p=Path.Combine(Dir,"step-"+(++N).ToString("D3")+"-"+label);var before=State();Write(p+".before.json",before);try{return fn();}finally{var after=State();Write(p+".after.json",after);if((long)before["foreground_hwnd"]!=(long)after["foreground_hwnd"])throw new Exception("OS foreground HWND changed during "+label);}}
 static void Guard(string s,Action a){Guard<int>(s,delegate{a();return 0;});}
 static Dictionary<string,object> Row(IZDoc d){string p=d.Name;bool own=Path.IsPathRooted(p)&&Own.Contains(Full(p));if(Path.GetFileName(p).ToLowerInvariant().Contains("epson")||Path.GetFileName(p).ToLowerInvariant().Contains("showcase"))own=false;return new Dictionary<string,object>{{"path",p},{"guid",d.FileGUID},{"modified",d.Modified},{"read_only",d.IsReadOnly()},{"owned_prototype",own},{"disk_sha256",File.Exists(p)?Hash(p):null}};}
 static List<IZDoc> Docs(List<string> errors){var list=new List<IZDoc>();var paths=new HashSet<string>(StringComparer.OrdinalIgnoreCase);try{var all=App.GetAllOpenDocs() as IEnumerable;if(all==null)throw new Exception("GetAllOpenDocs not enumerable");foreach(object o in all){var d=(IZDoc)o;if(paths.Add(d.Name))list.Add(d);}return list;}catch(Exception e){errors.Add("GetAllOpenDocs: "+e.Message);}try{var d=App.ActiveDoc;if(d!=null&&paths.Add(d.Name))list.Add(d);}catch(Exception e){errors.Add("ActiveDoc getter: "+e.Message);}foreach(string p in Own){try{var d=App.GetOpenDocByName(p);if(d!=null&&Same(d.Name,p)&&paths.Add(d.Name))list.Add(d);}catch(Exception e){errors.Add("Exact lookup "+p+": "+e.Message);}}return list;}
 [STAThread]static int Main(string[] args){try{var req=Obj(J.DeserializeObject(File.ReadAllText(args[0])));Dir=Full((string)req["directory"]);Own=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(object p in Arr(req["whitelist"]))Own.Add(Full((string)p));dynamic legacy=Existing(Arr(req["contexts"]));App=(IZBaseApp)legacy.Application.ZIronCADApp;
 var errors=new List<string>();var docs=Guard("inventory",()=>Docs(errors));var rows=new List<object>();foreach(var d in docs)rows.Add(Row(d));int count=Guard("count-before",()=>App.GetOpenDocsCount());
 if((string)req["action"]=="inventory"){Write(Path.Combine(Dir,"inventory_before.json"),new{read_only=true,documents=rows,all_enumerated_count=docs.Count,api_open_doc_count=count,enumeration_errors=errors,state=State(),whitelist=Own});Console.WriteLine(J.Serialize(new{inventory=Path.Combine(Dir,"inventory_before.json"),count=docs.Count,api_open_doc_count=count,documents=rows,errors=errors}));Environment.Exit(0);return 0;}
 var prior=Obj(J.DeserializeObject(File.ReadAllText(Path.Combine(Dir,"inventory_before.json"))));var allowed=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(object o in Arr(prior["documents"])){var r=Obj(o);if((bool)r["owned_prototype"])allowed.Add(Full((string)r["path"]));}
 var closed=new List<object>();var skipped=new List<object>();int i=0;long foreground=GetForegroundWindow().ToInt64();
 docs.Sort((a,b)=>{bool ac=Same(a.Name,(string)req["primary_context"]),bc=Same(b.Name,(string)req["primary_context"]);return ac==bc?0:(ac?1:-1);});
 foreach(var d in docs){var r=Row(d);string original=d.Name;if(!(bool)r["owned_prototype"]||!allowed.Contains(Full(original))){skipped.Add(r);continue;}string backup=null,saved=null;string oldHash=File.Exists(original)?Hash(original):null;
  if(d.Modified){int k=++i;backup=Path.Combine(Dir,"prototype-"+k.ToString("D3")+"-memory-backup.ics");saved=Path.Combine(Dir,"prototype-"+k.ToString("D3")+"-saved-work.ics");var scene=(IZSceneDoc)d;Guard("backup-"+k,()=>scene.SaveAsCopy(backup,eZLinksSaveOptions.Z_LINKS_COPY_ALL,false));if(!File.Exists(backup)||new FileInfo(backup).Length==0)throw new Exception("Memory backup missing");Guard("save-owned-new-"+k,()=>scene.SaveAs(saved,eZLinksSaveOptions.Z_LINKS_COPY_ALL,false));if(d.Modified||!Same(d.Name,saved))throw new Exception("New own work copy not clean");}
  if(d.Modified)throw new Exception("Refusing dirty close");string pathAtClose=d.Name;Guard("close-owned",()=>d.Close());if(oldHash!=null&&Hash(original)!=oldHash)throw new Exception("Original prototype bytes unexpectedly changed");
  var receipt=new{original_path=original,original_sha256_unchanged=oldHash,closed_path=pathAtClose,was_modified=(bool)r["modified"],backup_path=backup,backup_sha256=backup==null?null:Hash(backup),saved_work_path=saved,saved_work_sha256=saved==null?null:Hash(saved)};closed.Add(receipt);Write(Path.Combine(Dir,"closed-"+closed.Count.ToString("D3")+".json"),receipt);
 }
 var afterErrors=new List<string>();var remaining=Guard("inventory-after",()=>Docs(afterErrors));var afterRows=new List<object>();foreach(var d in remaining)afterRows.Add(Row(d));int afterCount=Guard("count-after",()=>App.GetOpenDocsCount());if(GetForegroundWindow().ToInt64()!=foreground)throw new Exception("OS foreground changed during cleanup session");
 Write(Path.Combine(Dir,"cleanup_receipt.json"),new{passed=true,closed_count=closed.Count,closed=closed,skipped=skipped,before_api_open_doc_count=count,after_api_open_doc_count=afterCount,before_enumerated_count=docs.Count,after_enumerated_count=remaining.Count,remaining_documents=afterRows,foreground_hwnd_unchanged=true,foreground_hwnd=foreground,enumeration_errors_before=errors,enumeration_errors_after=afterErrors,scope="Only exact whitelisted generated prototypes; unknown/original Epson preserved. Modified models saved to two new own copies, original prototype disk files preserved."});
 Console.WriteLine(J.Serialize(new{passed=true,closed_count=closed.Count,before_count=count,after_count=afterCount,remaining_documents=afterRows,receipt=Path.Combine(Dir,"cleanup_receipt.json")}));Environment.Exit(0);return 0;
 }catch(Exception e){Console.Error.WriteLine(e);Environment.Exit(1);return 1;}}
}
